// Package water 是本地取样与超标判定的本地基线。
package water

// Ready 表示基线可以运行。
func Ready() bool { return true }

content.content:
1	package water
2	
3	import (
4		"encoding/json"
5		"errors"
6		"fmt"
7		"io/fs"
8		"math"
9		"os"
10		"path/filepath"
11		"sort"
12		"strconv"
13		"strings"
14		"sync"
15		"time"
16		"unicode/utf8"
17	)
18	
19	// Status 表示样品所处的判定状态。
20	type Status string
21	
22	const (
23		// StatusPending 样品已录入，尚未确认判定结果。
24		StatusPending Status = "pending"
25		// StatusConfirmed 样品已确认，判定结果已保存。
26		StatusConfirmed Status = "confirmed"
27		// StatusVoided 样品已作废，保留记录但不能再确认。
28		StatusVoided Status = "voided"
29	)
30	
31	var (
32		ErrClosed             = errors.New("water: 数据存放已关闭")
33		ErrEmptyField         = errors.New("water: 编号、名称或项目去掉首尾空白后不能为空")
34		ErrDuplicatePoint     = errors.New("water: 采样点编号已登记")
35		ErrUnknownPoint       = errors.New("water: 采样点未登记")
36		ErrInvalidValue       = errors.New("water: 数值只接受有限数")
37		ErrInvalidTime        = errors.New("water: 采样时间或生效时间缺失")
38		ErrDuplicateLimitTime = errors.New("water: 同一采样点同一项目已存在相同生效时间的上限")
39		ErrUnknownSample      = errors.New("water: 样品编号不存在")
40		ErrSampleConflict     = errors.New("water: 同一编号提交的样品内容不一致")
41		ErrDuplicateItem      = errors.New("water: 同一份样品的测量项目重复")
42		ErrNoMeasurements     = errors.New("water: 样品至少需要一个项目的测量值")
43		ErrMissingLimit       = errors.New("water: 存在找不到适用上限的测量项目")
44		ErrVoided             = errors.New("water: 样品已作废，不能再确认")
45		ErrVoidReasonConflict = errors.New("water: 作废原因与已有记录不一致")
46		ErrInvalidText        = errors.New("water: 采样点编号、名称、项目名或样品编号不是合法的 UTF-8 文本")
47	)
48	
49	// SamplingPoint 是按编号唯一登记的采样点。
50	type SamplingPoint struct {
51		ID   string `json:"id"`
52		Name string `json:"name"`
53	}
54	
55	// Limit 是某采样点某测量项目的一版数值上限。
56	type Limit struct {
57		PointID   string    `json:"pointId"`
58		Item      string    `json:"item"`
59		Value     float64   `json:"value"`
60		Effective time.Time `json:"effective"`
61	}
62	
63	// Measurement 是样品中一个项目的测量值。
64	type Measurement struct {
65		Item  string  `json:"item"`
66		Value float64 `json:"value"`
67	}
68	
69	// ItemResult 是确认后单个项目的判定结果。
70	type ItemResult struct {
71		Item           string    `json:"item"`
72		Value          float64   `json:"value"`
73		Limit          float64   `json:"limit"`
74		LimitEffective time.Time `json:"limitEffective"`
75		Exceeded       bool      `json:"exceeded"`
76	}
77	
78	// Sample 是一份从录入、确认到作废的样品记录。
79	type Sample struct {
80		ID           string        `json:"id"`
81		PointID      string        `json:"pointId"`
82		SampledAt    time.Time     `json:"sampledAt"`
83		Measurements []Measurement `json:"measurements"`
84		Status       Status        `json:"status"`
85		Results      []ItemResult  `json:"results,omitempty"`
86		Exceeded     bool          `json:"exceeded"`
87		VoidReason   string        `json:"voidReason,omitempty"`
88	}
89	
90	// diskState 是落盘的完整数据。
91	type diskState struct {
92		Points  map[string]SamplingPoint `json:"points"`
93		Limits  map[string][]Limit       `json:"limits"` // 键仅为落盘占位，读取时按每条限值自身的采样点与项目重新分组
94		Samples map[string]*Sample       `json:"samples"`
95	}
96	
97	// limitGroup 用两个字段各自标识一组限值，避免把包含 U+0000 的文本
98	// 用单字符拼接成键时不同组合撞成同一组。
99	type limitGroup struct {
100		pointID string
101		item    string
102	}
103	
104	// Store 是绑定到某个本地目录的取样判定数据存放。
105	// 不同目录的数据互不混用；关闭后重新打开仍能查看原有记录。
106	type Store struct {
107		mu      sync.Mutex
108		dir     string
109		file    string
110		closed  bool
111		points  map[string]SamplingPoint
112		limits  map[limitGroup][]Limit // 按生效时间升序
113		samples map[string]*Sample
114	}
115	
116	// Open 打开（必要时创建）dir 下的本地数据存放。
117	func Open(dir string) (*Store, error) {
118		if strings.TrimSpace(dir) == "" {
119			return nil, fmt.Errorf("%w: 数据目录", ErrEmptyField)
120		}
121		if err := os.MkdirAll(dir, 0o755); err != nil {
122			return nil, err
123		}
124		s := &Store{
125			dir:     dir,
126			file:    filepath.Join(dir, "water-data.json"),
127			points:  map[string]SamplingPoint{},
128			limits:  map[limitGroup][]Limit{},
129			samples: map[string]*Sample{},
130		}
131		data, err := os.ReadFile(s.file)
132		if errors.Is(err, fs.ErrNotExist) {
133			return s, nil
134		}
135		if err != nil {
136			return nil, err
137		}
138		var st diskState
139		if err := json.Unmarshal(data, &st); err != nil {
140			return nil, fmt.Errorf("water: 读取数据文件失败: %w", err)
141		}
142		if st.Points != nil {
143			s.points = st.Points
144		}
145		if st.Limits != nil {
146			// 不按落盘键分组：键可能是旧版本用单字符拼接生成的，包含 U+0000 的
147			// 不同（采样点，项目）组合会共用同一个键。以每条限值自身的两个字段为准，
148			// 让曾经被错误合并的组在重新打开时也能各自归位。
149			for _, versions := range st.Limits {
150				for _, lim := range versions {
151					g := limitGroup{pointID: lim.PointID, item: lim.Item}
152					s.limits[g] = append(s.limits[g], lim)
153				}
154			}
155			for g, versions := range s.limits {
156				sort.Slice(versions, func(i, j int) bool { return versions[i].Effective.Before(versions[j].Effective) })
157				s.limits[g] = versions
158			}
159		}
160		if st.Samples != nil {
161			s.samples = st.Samples
162		}
163		return s, nil
164	}
165	
166	// Close 关闭数据存放。已保存的记录已落盘，重新 Open 同一目录即可查看。
167	func (s *Store) Close() error {
168		s.mu.Lock()
169		defer s.mu.Unlock()
170		if s.closed {
171			return nil
172		}
173		s.closed = true
174		return nil
175	}
176	
177	func clean(s string) string { return strings.TrimSpace(s) }
178	
179	// diskLimitKey 生成仅用于落盘 JSON 的分组键。带上两个字段的长度前缀，
180	// 任何包含 U+0000 的文本组合都不会撞键；读取时并不依赖该键分组。
181	func diskLimitKey(pointID, item string) string {
182		return strconv.Itoa(len(pointID)) + ":" + pointID + strconv.Itoa(len(item)) + ":" + item
183	}
184	
185	func finite(v float64) bool { return !math.IsNaN(v) && !math.IsInf(v, 0) }
186	
187	// invalidUTF8 报告文本是否无法作为合法 UTF-8 原样保存。必须在任何处理之前检查
188	// 提交的原始文本：落盘 JSON 会把非法字节（孤立的 0xFF、0xFE、不完整的多字节
189	// 序列等）静默替换成 U+FFFD，返回记录与保存内容会因此对不上，两个不同编号也
190	// 可能变成同一文本。真正的 U+FFFD（“�”）以及中文、U+0000 等都是合法字符，
191	// 不在拒绝之列；只在去首尾空白之外不做任何字符替换或归一化。
192	func invalidUTF8(s string) bool { return !utf8.ValidString(s) }
193	
194	func (s *Store) checkOpenLocked() error {
195		if s.closed {
196			return ErrClosed
197		}
198		return nil
199	}
200	
201	// persistLocked 把全部数据原子写回数据文件。只在成功变更后调用，
202	// 被拒绝的操作不会走到这里，因此不会留下新增或变更记录。
203	func (s *Store) persistLocked() error {
204		diskLimits := make(map[string][]Limit, len(s.limits))
205		for g, versions := range s.limits {
206			diskLimits[diskLimitKey(g.pointID, g.item)] = versions
207		}
208		data, err := json.MarshalIndent(diskState{
209			Points:  s.points,
210			Limits:  diskLimits,
211			Samples: s.samples,
212		}, "", "  ")
213		if err != nil {
214			return err
215		}
216		tmp := s.file + ".tmp"
217		if err := os.WriteFile(tmp, data, 0o644); err != nil {
218			return err
219		}
220		return os.Rename(tmp, s.file)
221	}
222	
223	// RegisterPoint 登记采样点。编号、名称去掉首尾空白后不能为空，
224	// 保存和比较均使用处理后的文本；重复编号拒绝。
225	// 编号和名称必须都是合法的 UTF-8 文本：任一字段含孤立的 0xFF、0xFE 字节
226	// 或不完整的多字节序列等无法原样保存的内容时，整次登记以 ErrInvalidText
227	// 拒绝，不占用编号、不改动任何已有采样点；即使另一项为空白，或编号已登记而
228	// 这次名称含非法字节，也报告编码错误。真正的 U+FFFD（“�”）、中文和文本内部
229	// 的 U+0000 仍是合法字符。
230	func (s *Store) RegisterPoint(id, name string) (SamplingPoint, error) {
231		s.mu.Lock()
232		defer s.mu.Unlock()
233		if err := s.checkOpenLocked(); err != nil {
234			return SamplingPoint{}, err
235		}
236		// 在去首尾空白和其它任何处理之前检查原始文本：落盘 JSON 会把非法 UTF-8
237		// 静默替换成 U+FFFD，登记“成功”后保存的编号或名称就会与填写内容对不上，
238		// 两个不同编号（如末尾分别带孤立 0xFF、0xFE）还可能保存成同一编号；
239		// 只有整次拒绝才能保证采样点身份在保存前后一致。
240		if invalidUTF8(id) || invalidUTF8(name) {
241			return SamplingPoint{}, ErrInvalidText
242		}
243		id, name = clean(id), clean(name)
244		if id == "" || name == "" {
245			return SamplingPoint{}, ErrEmptyField
246		}
247		if _, ok := s.points[id]; ok {
248			return SamplingPoint{}, fmt.Errorf("%w: %s", ErrDuplicatePoint, id)
249		}
250		p := SamplingPoint{ID: id, Name: name}
251		s.points[id] = p
252		if err := s.persistLocked(); err != nil {
253			delete(s.points, id)
254			return SamplingPoint{}, err
255		}
256		return p, nil
257	}
258	
259	// SetLimit 为已登记采样点的某个测量项目登记一版数值上限及生效时间。
260	// 采样点编号和项目名必须是合法的 UTF-8 文本：任一字段含孤立的 0xFF、0xFE
261	// 字节或不完整的多字节序列等无法原样保存的内容时，整次登记以 ErrInvalidText
262	// 拒绝，不新增版本、不占用生效时间；真正的 U+FFFD（“�”）、中文和文本内部的
263	// U+0000 仍是合法字符。即使同次请求还存在采样点未登记、数值不是有限数或
264	// 生效时间缺失的问题，也报告文本编码错误。
265	// 允许乱序补录；生效时间相同（不同时区表示的同一时刻也算相同）的第二条拒绝。
266	func (s *Store) SetLimit(pointID, item string, value float64, effective time.Time) (Limit, error) {
267		s.mu.Lock()
268		defer s.mu.Unlock()
269		if err := s.checkOpenLocked(); err != nil {
270			return Limit{}, err
271		}
272		// 在去首尾空白和其它任何处理之前检查原始文本：落盘 JSON 会把非法 UTF-8
273		// 静默替换成 U+FFFD，登记“成功”后保存的项目名就会与填写内容对不上，
274		// 限值也不再属于实际填写的采样点和项目；只有整次拒绝才能保证一致。
275		if invalidUTF8(pointID) || invalidUTF8(item) {
276			return Limit{}, ErrInvalidText
277		}
278		pointID, item = clean(pointID), clean(item)
279		if pointID == "" || item == "" {
280			return Limit{}, ErrEmptyField
281		}
282		if _, ok := s.points[pointID]; !ok {
283			return Limit{}, fmt.Errorf("%w: %s", ErrUnknownPoint, pointID)
284		}
285		if !finite(value) {
286			return Limit{}, ErrInvalidValue
287		}
288		if effective.IsZero() {
289			return Limit{}, ErrInvalidTime
290		}
291		lim := Limit{PointID: pointID, Item: item, Value: value, Effective: effective.UTC()}
292		g := limitGroup{pointID: pointID, item: item}
293		versions := s.limits[g]
294		for _, v := range versions {
295			if v.Effective.Equal(lim.Effective) {
296				return Limit{}, fmt.Errorf("%w: %s/%s @ %s", ErrDuplicateLimitTime, pointID, item, lim.Effective)
297			}
298		}
299		old := s.limits[g]
300		// 复制到新切片再插入排序：append/sort 会原地改动共享底层数组，
301		// 一旦保存失败需要回滚，old 必须仍是调用前的完整状态。
302		versions = make([]Limit, len(old)+1)
303		copy(versions, old)
304		versions[len(old)] = lim
305		sort.Slice(versions, func(i, j int) bool { return versions[i].Effective.Before(versions[j].Effective) })
306		s.limits[g] = versions
307		if err := s.persistLocked(); err != nil {
308			s.limits[g] = old
309			return Limit{}, err
310		}
311		return lim, nil
312	}
313	
314	// SubmitSample 录入一份样品，初始为待判定状态。
315	// 样品编号、采样点编号和每个项目名必须是合法的 UTF-8 文本：任一字段含孤立的
316	// 0xFF、0xFE 字节或不完整的多字节序列等无法原样保存的内容时，整份提交以
317	// ErrInvalidText 拒绝，不留部分记录，也不占用编号；真正的 U+FFFD（“�”）
318	// 仍是合法字符。再次提交同一编号且内容相同（项目排列顺序不同不算变化）返回原样品；
319	// 任一内容不同则拒绝整个提交，已确认或已作废的样品同样遵守。
320	func (s *Store) SubmitSample(id, pointID string, sampledAt time.Time, measurements ...Measurement) (Sample, error) {
321		s.mu.Lock()
322		defer s.mu.Unlock()
323		if err := s.checkOpenLocked(); err != nil {
324			return Sample{}, err
325		}
326		// 在去首尾空白和其它任何处理之前检查原始文本：落盘 JSON 会把非法 UTF-8
327		// 静默替换成 U+FFFD，只有整份拒绝才能保证返回记录、按点查看与保存数据一致。
328		// 即使编号已被已有样品占用、非法项目排在最后，或提交同时存在其它内容问题，
329		// 也必须报告编码问题：不能归为未知采样点、项目重复或同编号冲突，更不能走
330		// 重复录入成功的分支。
331		if invalidUTF8(id) || invalidUTF8(pointID) {
332			return Sample{}, ErrInvalidText
333		}
334		for _, m := range measurements {
335			if invalidUTF8(m.Item) {
336				return Sample{}, ErrInvalidText
337			}
338		}
339		id, pointID = clean(id), clean(pointID)
340		if id == "" || pointID == "" {
341			return Sample{}, ErrEmptyField
342		}
343		if sampledAt.IsZero() {
344			return Sample{}, ErrInvalidTime
345		}
346		if len(measurements) == 0 {
347			return Sample{}, ErrNoMeasurements
348		}
349		ms := make([]Measurement, len(measurements))
350		seen := make(map[string]float64, len(measurements))
351		for i, m := range measurements {
352			item := clean(m.Item)
353			if item == "" {
354				return Sample{}, ErrEmptyField
355			}
356			if !finite(m.Value) {
357				return Sample{}, ErrInvalidValue
358			}
359			if _, dup := seen[item]; dup {
360				return Sample{}, fmt.Errorf("%w: %s", ErrDuplicateItem, item)
361			}
362			seen[item] = m.Value
363			ms[i] = Measurement{Item: item, Value: m.Value}
364		}
365		sampledAt = sampledAt.UTC()
366	
367		if existing, ok := s.samples[id]; ok {
368			if sameSampleContent(existing, pointID, sampledAt, seen) {
369				return copySample(existing), nil
370			}
371			return Sample{}, fmt.Errorf("%w: %s", ErrSampleConflict, id)
372		}
373		if _, ok := s.points[pointID]; !ok {
374			return Sample{}, fmt.Errorf("%w: %s", ErrUnknownPoint, pointID)
375		}
376		smp := &Sample{
377			ID:           id,
378			PointID:      pointID,
379			SampledAt:    sampledAt,
380			Measurements: ms,
381			Status:       StatusPending,
382		}
383		s.samples[id] = smp
384		if err := s.persistLocked(); err != nil {
385			delete(s.samples, id)
386			return Sample{}, err
387		}
388		return copySample(smp), nil
389	}
390	
391	func sameSampleContent(s *Sample, pointID string, sampledAt time.Time, ms map[string]float64) bool {
392		if s.PointID != pointID || !s.SampledAt.Equal(sampledAt) || len(s.Measurements) != len(ms) {
393			return false
394		}
395		for _, m := range s.Measurements {
396			v, ok := ms[m.Item]
397			if !ok || v != m.Value {
398				return false
399			}
400		}
401		return true
402	}
403	
404	// Confirm 确认一份待判定样品：每个项目取生效时间不晚于采样时间的最近一版上限，
405	// 测量值大于上限才超标，任一项目超标则整份样品超标。
406	// 只要有项目找不到适用上限，本次确认拒绝，样品保持待判定。
407	// 重复确认直接返回已保存结果；之后新增或补录限值不改变已确认结果。
408	func (s *Store) Confirm(id string) (Sample, error) {
409		s.mu.Lock()
410		defer s.mu.Unlock()
411		if err := s.checkOpenLocked(); err != nil {
412			return Sample{}, err
413		}
414		id = clean(id)
415		if id == "" {
416			return Sample{}, ErrEmptyField
417		}
418		smp, ok := s.samples[id]
419		if !ok {
420			return Sample{}, fmt.Errorf("%w: %s", ErrUnknownSample, id)
421		}
422		switch smp.Status {
423		case StatusVoided:
424			return Sample{}, fmt.Errorf("%w: %s", ErrVoided, id)
425		case StatusConfirmed:
426			return copySample(smp), nil
427		}
428	
429		results := make([]ItemResult, 0, len(smp.Measurements))
430		exceeded := false
431		for _, m := range smp.Measurements {
432			lim, ok := applicableLimit(s.limits[limitGroup{pointID: smp.PointID, item: m.Item}], smp.SampledAt)
433			if !ok {
434				return Sample{}, fmt.Errorf("%w: 样品 %s 的项目 %s", ErrMissingLimit, id, m.Item)
435			}
436			ex := m.Value > lim.Value
437			if ex {
438				exceeded = true
439			}
440			results = append(results, ItemResult{
441				Item:           m.Item,
442				Value:          m.Value,
443				Limit:          lim.Value,
444				LimitEffective: lim.Effective,
445				Exceeded:       ex,
446			})
447		}
448		smp.Results = results
449		smp.Exceeded = exceeded
450		smp.Status = StatusConfirmed
451		if err := s.persistLocked(); err != nil {
452			smp.Results = nil
453			smp.Exceeded = false
454			smp.Status = StatusPending
455			return Sample{}, err
456		}
457		return copySample(smp), nil
458	}
459	
460	// applicableLimit 在按生效时间升序的版本里取不晚于 at 的最近一版；
461	// 采样时间恰好等于生效时间时使用该版新值。
462	func applicableLimit(versions []Limit, at time.Time) (Limit, bool) {
463		best := -1
464		for i, v := range versions {
465			if v.Effective.After(at) {
466				break
467			}
468			best = i
469		}
470		if best < 0 {
471			return Limit{}, false
472		}
473		return versions[best], true
474	}
475	
476	// Void 作废样品。原因去掉首尾空白后不能为空；待判定和已确认的样品都能作废。
477	// 作废后保留测量、原因和已有结果；重复提交处理后相同的原因返回原记录，不同则拒绝。
478	func (s *Store) Void(id, reason string) (Sample, error) {
479		s.mu.Lock()
480		defer s.mu.Unlock()
481		if err := s.checkOpenLocked(); err != nil {
482			return Sample{}, err
483		}
484		id, reason = clean(id), clean(reason)
485		if id == "" || reason == "" {
486			return Sample{}, ErrEmptyField
487		}
488		smp, ok := s.samples[id]
489		if !ok {
490			return Sample{}, fmt.Errorf("%w: %s", ErrUnknownSample, id)
491		}
492		if smp.Status == StatusVoided {
493			if smp.VoidReason == reason {
494				return copySample(smp), nil
495			}
496			return Sample{}, fmt.Errorf("%w: %s", ErrVoidReasonConflict, id)
497		}
498		oldStatus := smp.Status
499		smp.Status = StatusVoided
500		smp.VoidReason = reason
501		if err := s.persistLocked(); err != nil {
502			smp.Status = oldStatus
503			smp.VoidReason = ""
504			return Sample{}, err
505		}
506		return copySample(smp), nil
507	}
508	
509	// ListByPoint 按采样点查看样品，按采样时间从晚到早排列，同一时刻按样品编号升序。
510	func (s *Store) ListByPoint(pointID string) ([]Sample, error) {
511		s.mu.Lock()
512		defer s.mu.Unlock()
513		if err := s.checkOpenLocked(); err != nil {
514			return nil, err
515		}
516		return s.pointSamplesLocked(clean(pointID), func(*Sample) bool { return true }), nil
517	}
518	
519	// LatestResult 返回该采样点最近有效的已确认样品（跳过待判定与已作废）。
520	// 没有已确认且未作废的样品时 ok 为 false。
521	func (s *Store) LatestResult(pointID string) (smp Sample, ok bool, err error) {
522		s.mu.Lock()
523		defer s.mu.Unlock()
524		if err := s.checkOpenLocked(); err != nil {
525			return Sample{}, false, err
526		}
527		list := s.pointSamplesLocked(clean(pointID), func(smp *Sample) bool {
528			return smp.Status == StatusConfirmed
529		})
530		if len(list) == 0 {
531			return Sample{}, false, nil
532		}
533		return list[0], true, nil
534	}
535	
536	// pointSamplesLocked 收集某采样点符合 keep 的样品，逐份复制后按统一规则排列，
537	// 供 ListByPoint 与 LatestResult 共用，保证两种查询对同一批样品的先后判断一致。
538	// 调用方须已持有锁；pointID 须已做首尾空白处理。
539	func (s *Store) pointSamplesLocked(pointID string, keep func(*Sample) bool) []Sample {
540		var list []Sample
541		for _, smp := range s.samples {
542			if smp.PointID == pointID && keep(smp) {
543				list = append(list, copySample(smp))
544			}
545		}
546		sortSamples(list)
547		return list
548	}
549	
550	func sortSamples(list []Sample) {
551		sort.Slice(list, func(i, j int) bool {
552			a, b := list[i], list[j]
553			if !a.SampledAt.Equal(b.SampledAt) {
554				return a.SampledAt.After(b.SampledAt)
555			}
556			return a.ID < b.ID
557		})
558	}
559	
560	func copySample(s *Sample) Sample {
561		c := *s
562		c.Measurements = append([]Measurement(nil), s.Measurements...)
563		c.Results = append([]ItemResult(nil), s.Results...)
564		return c
565	}
