78	// checkEarlierS0 完整核对最近有效结果退回的较早样品 S0：
79	// 返回内容必须整体属于 S0（pH 7、COD 20，两项与整份均达标），
80	// 不能混入作废记录 S1 的 pH 9、超标依据或任何字段。
81	func checkEarlierS0(t *testing.T, smp Sample, label string) {
82		t.Helper()
83		if smp.ID != "S0" || smp.PointID != "P1" || smp.Status != StatusConfirmed || smp.VoidReason != "" {
84			t.Fatalf("%s: 最近有效结果应整体属于较早的 S0: %+v", label, smp)
85		}
86		if !smp.SampledAt.Equal(at(5, 0)) {
87			t.Fatalf("%s: 采样时间不属于 S0: %+v", label, smp)
88		}
89		if smp.Exceeded || len(smp.Measurements) != 2 || len(smp.Results) != 2 {
90			t.Fatalf("%s: S0 应整份达标并带两项测量与判定: %+v", label, smp)
91		}
92		ms := map[string]float64{}
93		for _, m := range smp.Measurements {
94			ms[m.Item] = m.Value
95		}
96		if ms["pH"] != 7 || ms["COD"] != 20 {
97			t.Fatalf("%s: 不能混入作废记录 S1 的测量值: %+v", label, smp.Measurements)
98		}
99		rs := map[string]ItemResult{}
100		for _, r := range smp.Results {
101			rs[r.Item] = r
102		}
103		ph, cod := rs["pH"], rs["COD"]
104		if ph.Value != 7 || ph.Limit != 8.0 || !ph.LimitEffective.Equal(at(1, 0)) || ph.Exceeded {
105			t.Fatalf("%s: pH 应为 7 ≤ 8@09-01 达标: %+v", label, ph)
106		}
107		if cod.Value != 20 || cod.Limit != 30.0 || !cod.LimitEffective.Equal(at(1, 0)) || cod.Exceeded {
108			t.Fatalf("%s: COD 应为 20 ≤ 30@09-01 达标: %+v", label, cod)
109		}
110	}
