375					label, latest, earlier)
376			}
377		}
378	
379		// 1) 超标项 pH 改值（9 -> 10），其他内容一致：内容冲突。
380		conflictPH, err := s.SubmitSample(" S1 ", "P1", at(10, 0),
381			Measurement{Item: " pH ", Value: 10}, Measurement{Item: "COD", Value: 30})
382		if !errors.Is(err, ErrSampleConflict) {
383			t.Fatalf("pH 改值重报应报样品内容冲突, got %v", err)
384		}
