899		// 保存失败的条件下，空原因与不存在样品仍在保存之前的校验阶段拒绝，
900		// 用来证明下面 S2 的失败不是这类拒绝冒充的。
901		if _, err := s.Void("S2", "   "); !errors.Is(err, ErrEmptyField) {
902			t.Fatalf("blank reason should be rejected before save, got %v", err)
903		}
904		if _, err := s.Void("nope", "原因"); !errors.Is(err, ErrUnknownSample) {
905			t.Fatalf("unknown sample should be rejected before save, got %v", err)
906		}
907	
908		// 合法的作废请求（样品存在、已确认、原因非空）走到保存阶段后失败：
909		// 必须返回保存错误，不能返回作废成功的记录。
910		failedReason := "  采样瓶破损  "
911		got, err := s.Void("S2", failedReason)
912		if err == nil {
913			t.Fatal("Void should fail when the void record cannot be saved")
914		}
915		for _, target := range []error{ErrEmptyField, ErrUnknownSample, ErrVoided, ErrVoidReasonConflict} {
916			if errors.Is(err, target) {
917				t.Fatalf("save failure must not be reported as %v: %v", target, err)
918			}
919		}
920		if got.ID != "" || got.Status == StatusVoided {
921			t.Fatalf("failed save must not return a voided sample: %+v", got)
922		}
923	
924		// 失败后按采样点查看：较晚样品仍为已确认、作废原因为空，
925		// 编号、采样点、采样时间、两个项目的原始测量与原判定依据全部保持原样。
926		list, err := s.ListByPoint("P1")
927		if err != nil || len(list) != 2 {
928			t.Fatalf("ListByPoint after failed save: %+v err=%v", list, err)
929		}
930		checkLater(find(list, "S2"), StatusConfirmed, "", "失败后按点查看")
931		if s1 := find(list, "S1"); s1.Status != StatusConfirmed || s1.Exceeded || s1.VoidReason != "" {
932			t.Fatalf("较早样品不应受失败作废影响: %+v", s1)
933		}
934	
935		// 最近有效结果仍指向较晚的 S2，不能退到 S1，也不能变成没有结果。
936		latest, ok, err := s.LatestResult("P1")
937		if err != nil || !ok || latest.ID != "S2" {
938			t.Fatalf("latest valid result should stay S2, got %+v ok=%v err=%v", latest, ok, err)
939		}
940		checkLater(latest, StatusConfirmed, "", "失败后最近有效结果")
941	
942		// 再次确认应返回原来保存的结论，不能因失败的作废请求拒绝确认。
943		again, err := s.Confirm("S2")
944		if err != nil {
945			t.Fatalf("re-confirm after failed void: %v", err)
946		}
947		checkLater(again, StatusConfirmed, "", "失败后重复确认")
948	
949		// 恢复正常保存条件
950		if err := os.Remove(tmp); err != nil {
951			t.Fatalf("restore persist: %v", err)
952		}
953	
954		// 用另一个合法原因重新作废同一份样品：必须成功，
955		// 不能把上次失败时填写的原因当成已有原因而报冲突。
956		v, err := s.Void("S2", "复测确认超标")
957		if err != nil {
958			t.Fatalf("retry Void after save restored: %v", err)
959		}
960		if v.Status != StatusVoided || v.VoidReason != "复测确认超标" || v.VoidReason == failedReason {
961			t.Fatalf("void should be saved with the new reason, got %+v", v)
962		}
963		// 成功记录保留两个项目的原始测量和原判定依据，并显示本次提交的原因
964		checkLater(v, StatusVoided, "复测确认超标", "成功作废返回值")
965	
966		// 按点查看仍能找到作废记录，原测量与原判定依据保留；最近有效结果改为较早的 S1
967		list2, err := s.ListByPoint("P1")
968		if err != nil {
969			t.Fatalf("ListByPoint after recovery: %v", err)
970		}
971		checkLater(find(list2, "S2"), StatusVoided, "复测确认超标", "成功作废后按点查看")
972		latest2, ok, err := s.LatestResult("P1")
973		if err != nil || !ok || latest2.ID != "S1" {
974			t.Fatalf("latest valid result should fall back to S1, got %+v ok=%v err=%v", latest2, ok, err)
975		}
976		// 已作废样品再次确认明确拒绝
977		if _, err := s.Confirm("S2"); !errors.Is(err, ErrVoided) {
978			t.Fatalf("confirm voided sample should be rejected, got %v", err)
979		}
980		// 公开语义保持兼容：相同保存原因幂等返回，其它原因仍报冲突
981		if same, err := s.Void("S2", " 复测确认超标 "); err != nil || same.VoidReason != "复测确认超标" {
982			t.Fatalf("same reason should stay idempotent, got %+v err=%v", same, err)
983		}
984		if _, err := s.Void("S2", failedReason); !errors.Is(err, ErrVoidReasonConflict) {
985			t.Fatalf("a different reason should conflict with the saved one, got %v", err)
986		}
987	
988		// 重新打开同一数据存放：成功作废落盘，失败尝试不留任何痕迹
989		if err := s.Close(); err != nil {
990			t.Fatalf("Close: %v", err)
991		}
992		s2, err := Open(dir)
993		if err != nil {
994			t.Fatalf("reopen: %v", err)
995		}
996		defer s2.Close()
997		list3, err := s2.ListByPoint("P1")
998		if err != nil {
999			t.Fatalf("reopened ListByPoint: %v", err)
1000		}
1001		checkLater(find(list3, "S2"), StatusVoided, "复测确认超标", "重开后按点查看")
1002		if latest3, ok, err := s2.LatestResult("P1"); err != nil || !ok || latest3.ID != "S1" {
1003			t.Fatalf("reopened latest should be S1, got %+v ok=%v err=%v", latest3, ok, err)
1004		}
1005		if _, err := s2.Confirm("S2"); !errors.Is(err, ErrVoided) {
1006			t.Fatalf("reopened confirm voided should be rejected, got %v", err)
1007		}
1008	}
1009	
1010	func TestListAndLatest(t *testing.T) {
1011		s, _ := open(t)
1012		mustPoint(t, s, "P1", "取水口")
1013		mustPoint(t, s, "P2", "排水口")
1014		mustLimit(t, s, "P1", "pH", 8.0, at(1, 0))
1015		mustLimit(t, s, "P2", "pH", 8.0, at(1, 0))
1016	
1017		mustSample(t, s, "S2", "P1", at(5, 0), Measurement{Item: "pH", Value: 7})
1018		mustSample(t, s, "S1", "P1", at(5, 0), Measurement{Item: "pH", Value: 7}) // 同时刻，编号升序
1019		mustSample(t, s, "S3", "P1", at(8, 0), Measurement{Item: "pH", Value: 9})
1020		mustSample(t, s, "S4", "P1", at(9, 0), Measurement{Item: "pH", Value: 7})
1021		mustSample(t, s, "SX", "P2", at(10, 0), Measurement{Item: "pH", Value: 7})
1022	
1023		if _, err := s.Confirm("S3"); err != nil {
1024			t.Fatalf("Confirm S3: %v", err)
1025		}
1026		if _, err := s.Void("S4", "作废"); err != nil {
1027			t.Fatalf("Void S4: %v", err)
1028		}
1029	
1030		list, err := s.ListByPoint("P1")
1031		if err != nil {
1032			t.Fatalf("ListByPoint: %v", err)
1033		}
1034		ids := []string{list[0].ID, list[1].ID, list[2].ID, list[3].ID}
1035		want := []string{"S4", "S3", "S1", "S2"} // 时间晚到早，同时刻编号升序
1036		for i := range want {
1037			if ids[i] != want[i] {
1038				t.Fatalf("order = %v, want %v", ids, want)
1039			}
1040		}
1041		if list[1].Status != StatusConfirmed || !list[1].Exceeded {
1042			t.Fatalf("S3 should be confirmed & exceeded: %+v", list[1])
1043		}
1044		if list[1].Results[0].Value != 9 || list[1].Results[0].Limit != 8.0 {
1045			t.Fatalf("exceeded item should show value and limit: %+v", list[1].Results[0])
1046		}
1047		if list[0].Status != StatusVoided || list[2].Status != StatusPending {
1048			t.Fatalf("statuses wrong: %+v", list)
1049		}
1050	
1051		// 最近有效结果：跳过待判定与作废，取 S3
1052		latest, ok, err := s.LatestResult("P1")
1053		if err != nil || !ok || latest.ID != "S3" {
1054			t.Fatalf("latest = %+v ok=%v err=%v", latest, ok, err)
1055		}
1056	
1057		// 没有已确认且未作废的样品时明确无结果
1058		if _, ok, err := s.LatestResult("P2"); err != nil || ok {
1059			t.Fatalf("P2 should have no result, ok=%v err=%v", ok, err)
1060		}
1061	}
1062	
1063	func TestPersistenceAndIsolation(t *testing.T) {
1064		s, dir := open(t)
1065		mustPoint(t, s, "P1", "取水口")
1066		mustLimit(t, s, "P1", "pH", 8.0, at(1, 0))
1067		mustSample(t, s, "S1", "P1", at(2, 0), Measurement{Item: "pH", Value: 9})
1068		if _, err := s.Confirm("S1"); err != nil {
1069			t.Fatalf("Confirm: %v", err)
1070		}
