	"errors"
	"testing"
	"time"
)

// 本文件的测试只针对一件事：调用方拿到的样品记录是这次返回的副本，
// 为页面展示随意修改本地数据，既不能写回数据存放，也不能影响其他
// 已经返回的记录。ListByPoint、LatestResult、Confirm 的入口、返回含义
// 与排序规则保持现状。

// twoItemSaved 是"一项超标、一项恰好等于上限"的已确认样品应保存的完整内容。
func checkTwoItemSaved(t *testing.T, smp Sample, label string) {
	t.Helper()
	if smp.ID != "S1" || smp.PointID != "P1" || smp.Status != StatusConfirmed {
		t.Fatalf("%s: 样品基本字段被改动: %+v", label, smp)
	}
	if !smp.SampledAt.Equal(at(10, 0)) || smp.VoidReason != "" {
		t.Fatalf("%s: 采样时间或作废原因被改动: %+v", label, smp)
	}
	if !smp.Exceeded {
		t.Fatalf("%s: 整份样品应超标（pH 9 > 8）: %+v", label, smp)
	}
	if len(smp.Measurements) != 2 || len(smp.Results) != 2 {
		t.Fatalf("%s: 测量项目或判定结果数量被改动: %+v", label, smp)
	}
	ms := map[string]float64{}
	for _, m := range smp.Measurements {
		ms[m.Item] = m.Value
	}
	if ms["pH"] != 9 || ms["COD"] != 30 {
		t.Fatalf("%s: 原测量值被改动: %+v", label, smp.Measurements)
	}
	rs := map[string]ItemResult{}
	for _, r := range smp.Results {
		rs[r.Item] = r
	}
	ph, ok := rs["pH"]
	if !ok || ph.Value != 9 || ph.Limit != 8.0 || !ph.LimitEffective.Equal(at(1, 0)) || !ph.Exceeded {
		t.Fatalf("%s: pH 应为 9 > 8@09-01 超标: %+v", label, ph)
	}
	cod, ok := rs["COD"]
	if !ok || cod.Value != 30 || cod.Limit != 30.0 || !cod.LimitEffective.Equal(at(1, 0)) || cod.Exceeded {
		t.Fatalf("%s: COD 30 == 上限 30@09-01 应达标: %+v", label, cod)
	}
}

// 同一采样点一份已确认样品（pH 9 > 上限 8 超标，COD 30 == 上限 30 达标）。
// 按点查询能看到原测量、每项所用上限与生效时间、单项与整份超标标记，
// 最近有效结果指向这份样品。调用方把返回记录里的项目名称、测量值、上限、
// 生效时间、超标标记乃至编号、状态全部改掉后，再次查询和重复确认仍必须
// 返回原来保存的内容。
func TestReturnedRecordMutationDoesNotWriteBack(t *testing.T) {
	s, _ := open(t)
	mustPoint(t, s, "P1", "取水口")
	mustLimit(t, s, "P1", "pH", 8.0, at(1, 0))
	mustLimit(t, s, "P1", "COD", 30.0, at(1, 0))
	mustSample(t, s, "S1", "P1", at(10, 0),
		Measurement{Item: "pH", Value: 9}, Measurement{Item: "COD", Value: 30})
	conf, err := s.Confirm("S1")
	if err != nil {
		t.Fatalf("Confirm: %v", err)
	}
	checkTwoItemSaved(t, conf, "confirm 返回值")

	list, err := s.ListByPoint("P1")
	if err != nil || len(list) != 1 {
		t.Fatalf("ListByPoint: %+v err=%v", list, err)
	}
	checkTwoItemSaved(t, list[0], "按点查询")
	latest, ok, err := s.LatestResult("P1")
	if err != nil || !ok || latest.ID != "S1" {
		t.Fatalf("最近有效结果应指向 S1: %+v ok=%v err=%v", latest, ok, err)
	}
	checkTwoItemSaved(t, latest, "最近有效结果")

	// 调用方为页面展示肆意修改拿到的记录：基本字段、测量、逐项判定全改
	m := list[0]
	m.ID = "HACK"
	m.PointID = "P9"
	m.SampledAt = at(1, 0)
	m.Status = StatusVoided
	m.Exceeded = false
	m.VoidReason = "伪造原因"
	m.Measurements[0].Item = "SS"
	m.Measurements[0].Value = 0.1
	m.Measurements[1].Value = 999
	m.Results[0].Item = "SS"
	m.Results[0].Value = 0.1
	m.Results[0].Limit = 1000
	m.Results[0].LimitEffective = at(20, 0)
	m.Results[0].Exceeded = false
	m.Results[1].Limit = 0.01
	m.Results[1].Exceeded = true

	// 再次查询：保存记录必须仍是原内容
	list2, err := s.ListByPoint("P1")
	if err != nil || len(list2) != 1 {
		t.Fatalf("ListByPoint after mutation: %+v err=%v", list2, err)
	}
	checkTwoItemSaved(t, list2[0], "修改后再次查询")
	// 重复确认：仍返回已保存结论，不能采纳调用方临时编辑的结果
	again, err := s.Confirm("S1")
	if err != nil {
		t.Fatalf("重复确认: %v", err)
	}
	checkTwoItemSaved(t, again, "修改后重复确认")
	// 最近有效结果也不受影响
	latest2, ok, err := s.LatestResult("P1")
	if err != nil || !ok {
		t.Fatalf("修改后最近有效结果: %+v ok=%v err=%v", latest2, ok, err)
	}
	checkTwoItemSaved(t, latest2, "修改后最近有效结果")
	// 修改前取得的 latest 副本保持取得时的内容
	checkTwoItemSaved(t, latest, "先前取得的最近有效结果")
}

// 列表记录与最近有效结果分别取得时互不影响：改其中一份，另一份保持原样；
// 改掉本地记录的编号、采样点、采样时间或状态，不能改变保存记录的归属、
// 排列位置和是否属于最近有效结果；两个项目的原始测量与判定依据都保持完整，
// 不允许只保住整份超标标记而某个项目被替换。
func TestListAndLatestRecordsAreIndependent(t *testing.T) {
	s, _ := open(t)
	mustPoint(t, s, "P1", "取水口")
	mustPoint(t, s, "P2", "排水口")
	mustLimit(t, s, "P1", "pH", 8.0, at(1, 0))
	mustLimit(t, s, "P1", "COD", 30.0, at(1, 0))
	mustLimit(t, s, "P2", "pH", 8.0, at(1, 0))

	// S0 较早、S1 较晚且为双项目样品；P2 的 SX 用来检查归属不被改写
	mustSample(t, s, "S0", "P1", at(5, 0), Measurement{Item: "pH", Value: 7})
	mustSample(t, s, "S1", "P1", at(10, 0),
		Measurement{Item: "pH", Value: 9}, Measurement{Item: "COD", Value: 30})
	mustSample(t, s, "SX", "P2", at(20, 0), Measurement{Item: "pH", Value: 7})
	if _, err := s.Confirm("S0"); err != nil {
		t.Fatalf("Confirm S0: %v", err)
	}
	if _, err := s.Confirm("S1"); err != nil {
		t.Fatalf("Confirm S1: %v", err)
	}

	list, err := s.ListByPoint("P1")
	if err != nil || len(list) != 2 {
		t.Fatalf("ListByPoint: %+v err=%v", list, err)
	}
	if list[0].ID != "S1" || list[1].ID != "S0" {
		t.Fatalf("排列应为 S1 在前 S0 在后: %+v", list)
	}
	latest, ok, err := s.LatestResult("P1")
	if err != nil || !ok || latest.ID != "S1" {
		t.Fatalf("最近有效结果应为 S1: %+v ok=%v err=%v", latest, ok, err)
	}

	// 改最近有效结果这份记录：换掉其中一个项目的判定、伪造归属与状态
	latest.ID = "S0"
	latest.PointID = "P2"
	latest.SampledAt = at(1, 0)
	latest.Status = StatusVoided
	latest.Exceeded = false
	latest.Results[1] = ItemResult{Item: "SS", Value: 1, Limit: 2, LimitEffective: at(2, 0), Exceeded: false}
	latest.Measurements = append(latest.Measurements, Measurement{Item: "SS", Value: 1})

	// 列表里先取得的那份记录不受 latest 副本修改的影响
	checkTwoItemSaved(t, list[0], "修改 latest 后列表中的记录")

	// 再改列表记录：编号、采样点、采样时间、状态全部伪造
	list[0].ID = "ZZZ"
	list[0].PointID = "P2"
	list[0].SampledAt = time.Time{}
	list[0].Status = StatusPending
	list[0].Results[0].Exceeded = false

	// 保存记录的归属、排列位置、最近有效结果身份不变
	list2, err := s.ListByPoint("P1")
	if err != nil || len(list2) != 2 {
		t.Fatalf("修改后 ListByPoint: %+v err=%v", list2, err)
	}
	if list2[0].ID != "S1" || list2[1].ID != "S0" {
		t.Fatalf("修改本地记录不应改变排列位置: %+v", list2)
	}
	checkTwoItemSaved(t, list2[0], "修改列表记录后再次查询")
	// 两个项目各自的原始测量与判定依据都完整，COD 一项不能被替换掉
	if list2[0].Results[0].Item == "SS" || list2[0].Results[1].Item == "SS" {
		t.Fatalf("某个项目被替换: %+v", list2[0].Results)
	}
	latest2, ok, err := s.LatestResult("P1")
	if err != nil || !ok || latest2.ID != "S1" {
		t.Fatalf("修改本地记录不应改变最近有效结果: %+v ok=%v err=%v", latest2, ok, err)
	}
	checkTwoItemSaved(t, latest2, "修改后最近有效结果")
	// P2 的归属不被伪造的 PointID 改变
	listP2, err := s.ListByPoint("P2")
	if err != nil || len(listP2) != 1 || listP2[0].ID != "SX" {
		t.Fatalf("P2 的样品归属被改动: %+v err=%v", listP2, err)
	}
}

// 已确认样品经正常作废后，按点查询保留原测量、原判定结果和作废原因。
// 调用方把查询得到的作废记录改回已确认、清空作废原因，不能使保存记录
// 恢复有效：再次确认仍拒绝，最近有效结果继续排除它，没有其他有效结果时
// 明确无结果。作废前取得的已确认记录保持取得时的内容。
func TestVoidedRecordMutationDoesNotRevive(t *testing.T) {
	s, _ := open(t)
	mustPoint(t, s, "P1", "取水口")
	mustLimit(t, s, "P1", "pH", 8.0, at(1, 0))
	mustLimit(t, s, "P1", "COD", 30.0, at(1, 0))
	mustSample(t, s, "S1", "P1", at(10, 0),
		Measurement{Item: "pH", Value: 9}, Measurement{Item: "COD", Value: 30})
	before, err := s.Confirm("S1")
	if err != nil {
		t.Fatalf("Confirm: %v", err)
	}
	checkTwoItemSaved(t, before, "作废前确认")

	if _, err := s.Void("S1", "采样瓶破损"); err != nil {
		t.Fatalf("Void: %v", err)
	}

	checkVoided := func(smp Sample, label string) {
		t.Helper()
		if smp.Status != StatusVoided || smp.VoidReason != "采样瓶破损" {
			t.Fatalf("%s: 作废状态或原因被改动: %+v", label, smp)
		}
		// 原测量与原判定结果（含逐项依据和整份超标标记）保留
		if smp.ID != "S1" || smp.PointID != "P1" || !smp.SampledAt.Equal(at(10, 0)) {
			t.Fatalf("%s: 基本字段被改动: %+v", label, smp)
		}
		if !smp.Exceeded || len(smp.Measurements) != 2 || len(smp.Results) != 2 {
			t.Fatalf("%s: 原判定结果未保留: %+v", label, smp)
		}
		rs := map[string]ItemResult{}
		for _, r := range smp.Results {
			rs[r.Item] = r
		}
		if ph := rs["pH"]; ph.Value != 9 || ph.Limit != 8.0 || !ph.Exceeded {
			t.Fatalf("%s: pH 原判定未保留: %+v", label, ph)
		}
		if cod := rs["COD"]; cod.Value != 30 || cod.Limit != 30.0 || cod.Exceeded {
			t.Fatalf("%s: COD 原判定未保留: %+v", label, cod)
		}
	}

	list, err := s.ListByPoint("P1")
	if err != nil || len(list) != 1 {
		t.Fatalf("ListByPoint: %+v err=%v", list, err)
	}
	checkVoided(list[0], "作废后按点查询")

	// 作废前取得的已确认记录保持取得时的内容，不随作废操作变化
	checkTwoItemSaved(t, before, "作废后先前取得的记录")

	// 调用方把查询得到的作废记录改回已确认、清空作废原因、伪造结论
	forged := list[0]
	forged.Status = StatusConfirmed
	forged.VoidReason = ""
	forged.Exceeded = false
	forged.Results[0].Exceeded = false

	// 保存记录不能恢复有效：再次确认仍拒绝
	if _, err := s.Confirm("S1"); !errors.Is(err, ErrVoided) {
		t.Fatalf("已作废样品再次确认应拒绝, got %v", err)
	}
	// 最近有效结果继续排除该样品；没有其他有效结果时明确无结果
	if latest, ok, err := s.LatestResult("P1"); err != nil || ok {
		t.Fatalf("作废后应无最近有效结果: %+v ok=%v err=%v", latest, ok, err)
	}
	// 再次查询仍是作废记录，原测量、原判定与作废原因俱在
	list2, err := s.ListByPoint("P1")
	if err != nil || len(list2) != 1 {
		t.Fatalf("伪造后 ListByPoint: %+v err=%v", list2, err)
	}
	checkVoided(list2[0], "伪造后再次查询")
	// 正常重复作废（相同原因）仍返回保存的作废记录
	again, err := s.Void("S1", "采样瓶破损")
	if err != nil {
		t.Fatalf("重复作废: %v", err)
	}
	checkVoided(again, "重复作废返回值")
}

// 这份程序对应 README“样品作废”一节的完整示例：
// 同一采样点上两份已确认样品——较早的一份达标，较晚的一份至少一项超标；
// 作废较晚样品后，按点列表仍保留它的原测量与逐项判定依据（仅供核对历史），
// 最近有效结果则退到较早的已确认样品。另一个采样点只有一份未确认即作废的
// 待判定样品，用来说明作废不会凭空生成结论，且没有其他有效样品时
// 最近有效结果明确为“无结果”，不能把空返回或为假的超标标记解释成达标。
package main

import (
	"errors"
	"flag"
	"fmt"
	"log"
	"time"

	"github.com/descikazuyq/water-sample/water"
)

const layout = "2006-01-02 15:04:05 Z07:00"

func must(action string, err error) {
	if err != nil {
		log.Fatalf("%s 失败: %v", action, err)
	}
}

func statusText(st water.Status) string {
	switch st {
	case water.StatusPending:
		return "待判定"
	case water.StatusConfirmed:
		return "已确认"
	case water.StatusVoided:
		return "已作废"
	default:
		return string(st)
	}
}

// printSamples 打印状态、超标标记、作废原因以及逐项判定依据。
// 作废记录的历史依据和有效样品的当前判定用的是同一套字段，
// 读者需要结合“状态”区分两者，不能只看超标标记。
func printSamples(samples []water.Sample) {
	for _, smp := range samples {
		fmt.Printf("  样品 %s | 采样点 %s | 采样时间 %s | 状态 %s | 超标标记 %v\n",
			smp.ID, smp.PointID, smp.SampledAt.UTC().Format(layout),
			statusText(smp.Status), smp.Exceeded)
		if smp.VoidReason != "" {
			fmt.Printf("    作废原因：%s\n", smp.VoidReason)
		}
		if len(smp.Results) == 0 {
			fmt.Println("    逐项判定：无（没有已保存的判定依据）")
			continue
		}
		for _, r := range smp.Results {
			verdict := "达标"
			if r.Exceeded {
				verdict = "超标"
			}
			fmt.Printf("    逐项判定：项目 %s | 测量值 %g | 适用上限 %g（%s 生效）| %s\n",
				r.Item, r.Value, r.Limit, r.LimitEffective.UTC().Format(layout), verdict)
		}
	}
}

// printLatest 打印最近有效结果；没有已确认且未作废的样品时明确打印“无结果”，
// 不把空样品或记录里为假的超标标记解释成达标。
func printLatest(store *water.Store, pointID string) {
	latest, ok, err := store.LatestResult(pointID)
	must("查询最近有效结果", err)
	if !ok {
		fmt.Printf("  采样点 %s 的最近有效结果：无（没有已确认且未作废的样品；返回空样品编号 %q、状态 %q）\n",
			pointID, latest.ID, latest.Status)
		fmt.Println("  注意：这既不是达标也不是超标，不能把空返回或待判定记录的超标标记 false 当成达标。")
		return
	}
	fmt.Printf("  采样点 %s 的最近有效结果：\n", pointID)
	printSamples([]water.Sample{latest})
}

func main() {
	dir := flag.String("dir", "", "本地数据目录（指定一个空目录，不存在会自动创建）")
	flag.Parse()
	if *dir == "" {
		log.Fatal("请用 -dir 指定一个空的本地数据目录，例如：go run ./demo-void -dir ./water-data-void-demo")
	}

	store, err := water.Open(*dir)
	must("打开数据存放", err)
	defer func() {
		if err := store.Close(); err != nil {
			log.Printf("关闭数据存放: %v", err)
		}
	}()

	const pointID = "P1"
	const earlierID = "S-20260905-01"
	const laterID = "S-20260910-01"
	eff := time.Date(2026, 9, 1, 0, 0, 0, 0, time.UTC)
	earlierAt := time.Date(2026, 9, 5, 0, 0, 0, 0, time.UTC)
	laterAt := time.Date(2026, 9, 10, 0, 0, 0, 0, time.UTC)

	// 1) 登记采样点和两版上限：pH 8、COD 30，均在 2026-09-01 生效。
	_, err = store.RegisterPoint(pointID, "一号取水口")
	must("登记采样点", err)
	_, err = store.SetLimit(pointID, "pH", 8.0, eff)
	must("登记 pH 上限", err)
	_, err = store.SetLimit(pointID, "COD", 30.0, eff)
	must("登记 COD 上限", err)

	// 2) 较早样品（9/5 采样）：pH 7、COD 20，两项都不超标。
	_, err = store.SubmitSample(earlierID, pointID, earlierAt,
		water.Measurement{Item: "pH", Value: 7},
		water.Measurement{Item: "COD", Value: 20},
	)
	must("录入较早样品", err)
	earlier, err := store.Confirm(earlierID)
	must("确认较早样品", err)

	// 3) 较晚样品（9/10 采样）：pH 9 大于上限 8（超标），
	//    COD 30 恰好等于上限 30（达标），任一项目超标则整份样品超标。
	_, err = store.SubmitSample(laterID, pointID, laterAt,
		water.Measurement{Item: "pH", Value: 9},
		water.Measurement{Item: "COD", Value: 30},
	)
	must("录入较晚样品", err)
	later, err := store.Confirm(laterID)
	must("确认较晚样品", err)
	fmt.Println("两份样品均已确认（按采样时间从晚到早排列）：")
	printSamples([]water.Sample{later, earlier})

	// 4) 作废前，最近有效结果指向采样时间最晚的已确认样品，即较晚的超标样品。
	fmt.Println("作废前查询最近有效结果：")
	printLatest(store, pointID)

	// 5) 作废原因去掉首尾空白后不能为空。仅含空白的原因直接拒绝，
	//    返回空样品——先处理 err，不能把空样品当作作废成功。
	blank, err := store.Void(laterID, "   ")
	if err == nil {
		log.Fatal("作废原因仅含空白时不应成功")
	}
	if !errors.Is(err, water.ErrEmptyField) {
		log.Fatalf("预期空白字段错误，实际为: %v", err)
	}
	fmt.Printf("空白原因作废被拒绝：%v\n", err)
	fmt.Printf("（出错时返回值是空样品：编号 %q，状态 %q，不能当作作废成功）\n",
		blank.ID, blank.Status)

	// 6) 填写非空原因（两端空白会被去掉）后作废较晚样品。
	voided, err := store.Void(laterID, "  复测确认样品污染  ")
	must("作废较晚样品", err)
	fmt.Println("填写非空原因后作废成功，返回的作废记录：")
	printSamples([]water.Sample{voided})

	// 7) 按点列表：两份样品都在。较晚样品状态为已作废并带原因，
	//    作废前保存的测量值、所用上限、生效时间和逐项结论原样保留。
	list, err := store.ListByPoint(pointID)
	must("作废后按采样点查询", err)
	fmt.Println("作废后按采样点查询（作废记录仍列出，历史依据保留，仅供核对历史）：")
	printSamples(list)

	// 8) 最近有效结果跳过已作废样品，退到较早的达标样品；
	//    返回内容整体来自较早样品，不能混入较晚样品的 pH 9 等任何数据。
	fmt.Println("作废后查询最近有效结果（退到较早的已确认样品）：")
	printLatest(store, pointID)

	// 9) 对已作废样品再次确认：明确拒绝，返回空样品。
	reconfirmed, err := store.Confirm(laterID)
	if err == nil {
		log.Fatal("已作废样品再次确认不应成功")
	}
	if !errors.Is(err, water.ErrVoided) {
		log.Fatalf("预期样品已作废错误，实际为: %v", err)
	}
	fmt.Printf("对已作废样品再次确认被拒绝：%v\n", err)
	fmt.Printf("（出错时返回值是空样品：编号 %q，状态 %q，不能当作确认成功）\n",
		reconfirmed.ID, reconfirmed.Status)

	// 10) 拒绝不改变任何记录：作废状态、原因与历史依据继续保留。
	list, err = store.ListByPoint(pointID)
	must("拒绝后按采样点查询", err)
	fmt.Println("再次确认被拒绝后按采样点查询（作废状态、原因与历史依据不变）：")
	printSamples(list)
	var kept water.Sample
	for _, smp := range list {
		if smp.ID == laterID {
			kept = smp
		}
	}
	if kept.Status != water.StatusVoided || kept.VoidReason != "复测确认样品污染" ||
		!kept.Exceeded || len(kept.Results) != 2 {
		log.Fatalf("拒绝确认不得改变作废记录: %+v", kept)
	}

	// 11) 另一个采样点：一份录入后从未确认、直接作废的待判定样品。
	const point2ID = "P2"
	const pendingID = "S-20260912-01"
	pendingAt := time.Date(2026, 9, 12, 0, 0, 0, 0, time.UTC)
	_, err = store.RegisterPoint(point2ID, "二号取水口")
	must("登记第二个采样点", err)
	_, err = store.SetLimit(point2ID, "pH", 8.0, eff)
	must("登记第二个采样点的 pH 上限", err)
	pending, err := store.SubmitSample(pendingID, point2ID, pendingAt,
		water.Measurement{Item: "pH", Value: 7})
	must("录入待判定样品", err)
	fmt.Printf("另一份样品录入后不确认直接作废（录入时状态为 %s，尚无判定依据）：\n",
		statusText(pending.Status))
	voidedPending, err := store.Void(pendingID, "录入信息有误")
	must("作废待判定样品", err)
	printSamples([]water.Sample{voidedPending})
	if len(voidedPending.Results) != 0 || voidedPending.Exceeded {
		log.Fatalf("待判定样品作废后不应凭空获得结论: %+v", voidedPending)
	}

	// 12) 按点列表能查到这份作废记录，但它没有逐项判定；该点没有其他
	//     已确认且未作废的样品，最近有效结果明确表示“无结果”。
	list2, err := store.ListByPoint(point2ID)
	must("第二个采样点按点查询", err)
	fmt.Println("第二个采样点按点查询（作废记录可查，但没有逐项判定）：")
	printSamples(list2)
	fmt.Println("第二个采样点查询最近有效结果：")
	printLatest(store, point2ID)
}

	}
}

